	[request_id],
	[row_descriptor],
	[transaction_date],
	[merchant_ref_number],
	[merchant_id],
	[ics_applications],
	[auth_rcode],
	[auth_rflag],
	[auth_rmsg],
	[auth_reversal_rcode],
	[auth_reversal_rflag],
	[auth_reversal_rmsg],
	[bill_rcode],
	[bill_rflag],
	[bill_rmsg],
	[customer_firstname],
	[customer_lastname],
	[customer_email],
	[account_suffix],
	[customer_cc_expmo],
	[customer_cc_expyr],
	[customer_cc_startmo],
	[customer_cc_startyr],
	[customer_cc_issue_number],
	[payment_method],
	[currency],
	[auth_auth_avs],
	[auth_auth_code],
	[auth_cv_result],
	[payment_processor],
	[source],
	[subscription_id],
	[amount]
